insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('52f68e6b-4468-4651-aa0e-0f3292598636', 'N2', 'Vた／Nの ＋ 末(に)', 'Cuối cùng thì.../Kết quả là... (sau 1 quá trình dài, đắn đo)', NULL, 'Vた／Nの ＋ 末(に)', 'Diễn tả kết quả cuối cùng sau 1 quá trình dài suy nghĩ/trải qua nhiều việc', NULL, NULL, NULL, '{}', NULL, 72, 'Vた／Nの ＋ 末(に)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8d7eee96-0e09-43bf-98bf-dc60d24044b8', 'N2', 'N／Vる／Vている ＋ どころではない', 'Không phải trong hoàn cảnh để có thể.../Không còn tâm trí để... (hoàn cảnh không cho phép)', NULL, 'N／Vる／Vている ＋ どころではない', 'Diễn tả hoàn cảnh hiện tại không cho phép/không còn tâm trí để làm việc đã nêu', NULL, NULL, NULL, '{}', NULL, 72, 'N／Vる／Vている ＋ どころではない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('772b60ca-5b45-4809-815e-ae5b6756c587', 'N2', 'Vる／Vない／Nの ＋ おそれがある', 'E rằng.../Có khả năng... (nguy cơ xảy ra 1 điều không mong muốn)', NULL, 'Vる／Vない／Nの ＋ おそれがある', 'Cảnh báo về nguy cơ/khả năng xảy ra 1 điều không tốt', NULL, NULL, NULL, '{}', NULL, 72, 'Vる／Vない／Nの ＋ おそれがある', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e10024cb-204c-4070-a35a-e5269f118276', 'N2', 'Vて ＋ はじめて', 'Kể từ sau khi...thì mới.../Chỉ sau khi...mới... (nhận ra/hiểu ra sau khi trải qua)', NULL, 'Vて ＋ はじめて', 'Diễn tả việc chỉ nhận ra/hiểu được điều gì đó sau khi đã trải qua trải nghiệm cụ thể', NULL, NULL, NULL, '{}', NULL, 72, 'Vて ＋ はじめて', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('11967674-49fd-4a4c-ba25-61ade5b96622', 'N2', 'Vた ＋ きり／っきり', 'Kể từ lần đó... (không có gì xảy ra thêm nữa sau sự việc đã nêu)', NULL, 'Vた ＋ きり／っきり', 'Diễn tả 1 sự việc là lần cuối cùng, sau đó không còn xảy ra thêm gì nữa', NULL, NULL, NULL, '{}', NULL, 72, 'Vた ＋ きり／っきり', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0c4a8ac6-be1c-4d7b-bfe7-1b399868fee8', 'N2', 'N(の)／Vる ＋ に先立って', 'Trước khi... (mang tính trang trọng, chuẩn bị trước khi 1 việc quan trọng diễn ra)', NULL, 'N(の)／Vる ＋ に先立って', 'Diễn tả 1 hành động chuẩn bị/thực hiện trước khi 1 sự việc quan trọng diễn ra', NULL, NULL, NULL, '{}', NULL, 72, 'N(の)／Vる ＋ に先立って', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8726b890-de11-473c-9ada-eb8c077bb7b3', 'N2', 'Vた ＋ ところ', 'Sau khi... (thử làm 1 việc rồi phát hiện ra 1 sự thật)', NULL, 'Vた ＋ ところ', 'Diễn tả việc sau khi thử làm 1 hành động thì phát hiện ra 1 kết quả/sự thật', NULL, NULL, NULL, '{}', NULL, 72, 'Vた ＋ ところ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ca4baf4e-8459-43d0-be5a-ce9bf8814b2d', 'N2', 'V(普)／Aい(普)／Aな・である／N・Nである ＋ どころか', 'Chẳng những/lấy đâu ra...mà ngược lại/thậm chí... (phủ định mạnh, nhấn mạnh sự đối lập)', NULL, 'V(普)／Aい(普)／Aな・である／N・Nである ＋ どころか', 'Phủ định mạnh 1 điều rồi khẳng định sự thật hoàn toàn ngược lại/thậm chí hơn thế', NULL, NULL, NULL, '{}', NULL, 72, 'V(普)／Aい(普)／Aな・である／N・Nである ＋ どころか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('56b679c0-a7b0-412b-b2df-ede417349226', 'N2', 'Vる／Vない／Vている ＋ ようじゃ／ようでは', 'Nếu...như thế này thì... (mang sắc thái phê phán, cảnh báo hậu quả tiêu cực)', NULL, 'Vる／Vない／Vている ＋ ようじゃ／ようでは', 'Cảnh báo 1 hậu quả tiêu cực nếu tình trạng/cách hành xử hiện tại tiếp tục', NULL, NULL, NULL, '{}', NULL, 72, 'Vる／Vない／Vている ＋ ようじゃ／ようでは', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('83975527-6f65-4554-98ff-21c8a5612912', 'N2', 'Vます／Aな・であり／N・Nであり ＋ ながら(も)', 'Mặc dù...nhưng... (nghịch với thực tế/trạng thái đã nêu)', NULL, 'Vます／Aな・であり／N・Nであり ＋ ながら(も)', 'Diễn tả 1 hành động/trạng thái nghịch với thực tế/tình huống đã nêu trước đó', NULL, NULL, NULL, '{}', NULL, 72, 'Vます／Aな・であり／N・Nであり ＋ ながら(も)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('92fa2c07-487e-4986-ae14-a2050de06c26', 'N2', 'V(ます) ＋ つつ', 'Vừa...vừa... (=Vながら, đồng thời làm 2 việc, hoặc nghịch với nhận thức)', NULL, 'Vます ＋ つつ(も)', 'Diễn tả 2 hành động xảy ra đồng thời, hoặc nghịch với nhận thức của bản thân (đồng nghĩa Vながら)', NULL, NULL, NULL, '{}', NULL, 72, 'V(ます) ＋ つつ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7197daa1-747d-450c-92d1-a6cd055de591', 'N2', 'V普／Aい／Aな／Nの ＋ わりに(は)', 'Mặc dù.../So với...thì... (kết quả không tương xứng với tiêu chuẩn/điều kiện đã nêu)', NULL, 'V普／Aい／Aな／Nの ＋ わりに(は)', 'So sánh 1 kết quả với tiêu chuẩn/điều kiện đã nêu, nhấn mạnh sự không tương xứng', NULL, NULL, NULL, '{}', NULL, 72, 'V普／Aい／Aな／Nの ＋ わりに(は)', 'pdf', 'ok')
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 1, 'standard', '大げんかの末にその夫婦は離婚した。', 'Sau những trận cãi nhau to, đôi vợ chồng đó đã bỏ nhau.', '大げんか＿＿＿その夫婦は離婚した。', 'の末に', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 2, 'daily', '長い議論の末、結論が出た。', 'Sau cuộc tranh luận dài, kết luận đã được đưa ra.', '長い議論＿＿＿、結論が出た。', 'の末', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 3, 'daily', '何度も失敗した末に、ようやく成功した。', 'Sau nhiều lần thất bại, cuối cùng tôi cũng đã thành công.', '何度も失敗した＿＿＿、ようやく成功した。', '末に', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d7eee96-0e09-43bf-98bf-dc60d24044b8', NULL, 1, 'standard', '年末年始は忙しいので、ゆっくりしているどころではない。', 'Thời điểm cuối năm và đầu năm vì rất bận nên chẳng còn tâm trí nào để thong thả thoải mái được.', '年末年始は忙しいので、ゆっくりしている＿＿＿。', 'どころではない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d7eee96-0e09-43bf-98bf-dc60d24044b8', NULL, 2, 'daily', '頭が痛くて、勉強するどころではない。', 'Đau đầu quá nên không còn tâm trí đâu mà học.', '頭が痛くて、勉強する＿＿＿。', 'どころではない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d7eee96-0e09-43bf-98bf-dc60d24044b8', NULL, 3, 'daily', '仕事が忙しくて、旅行どころではない。', 'Công việc bận quá nên không có thời gian mà nghĩ đến du lịch.', '仕事が忙しくて、旅行＿＿＿。', 'どころではない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('772b60ca-5b45-4809-815e-ae5b6756c587', NULL, 1, 'standard', '今晩は大雨のおそれがある。', 'Tối nay có khả năng mưa lớn.', '今晩は大雨の＿＿＿。', 'おそれがある', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('772b60ca-5b45-4809-815e-ae5b6756c587', NULL, 2, 'daily', '台風が接近するおそれがある。', 'Có khả năng bão sẽ đến gần.', '台風が接近する＿＿＿。', 'おそれがある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('772b60ca-5b45-4809-815e-ae5b6756c587', NULL, 3, 'daily', '薬の副作用が出るおそれがあるので注意してください。', 'Vì có khả năng xuất hiện tác dụng phụ của thuốc nên hãy chú ý.', '薬の副作用が出る＿＿＿ので注意してください。', 'おそれがある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e10024cb-204c-4070-a35a-e5269f118276', NULL, 1, 'standard', 'この本を3回読んではじめて、内容を理解する事ができた。', 'Chỉ sau khi đọc 3 lần cuốn sách này tôi mới hiểu nội dung của nó.', 'この本を3回読んで＿＿＿、内容を理解する事ができた。', 'はじめて', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e10024cb-204c-4070-a35a-e5269f118276', NULL, 2, 'daily', '大人になってはじめて、親のありがたみが分かった。', 'Chỉ sau khi trưởng thành tôi mới hiểu được sự đáng quý của cha mẹ.', '大人になって＿＿＿、親のありがたみが分かった。', 'はじめて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e10024cb-204c-4070-a35a-e5269f118276', NULL, 3, 'daily', '病気になってはじめて、健康の大切さに気づいた。', 'Chỉ sau khi bị bệnh tôi mới nhận ra tầm quan trọng của sức khỏe.', '病気になって＿＿＿、健康の大切さに気づいた。', 'はじめて', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11967674-49fd-4a4c-ba25-61ade5b96622', NULL, 1, 'standard', '父とは5年前に会ったきり、連絡を取っていない。', 'Kể từ lần gặp bố vào 5 năm trước tôi đã không liên lạc gì với ông ấy.', '父とは5年前に会った＿＿＿、連絡を取っていない。', 'きり', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11967674-49fd-4a4c-ba25-61ade5b96622', NULL, 2, 'daily', '彼女は出て行ったきり、戻ってこない。', 'Cô ấy ra đi và từ đó không quay trở lại nữa.', '彼女は出て行った＿＿＿、戻ってこない。', 'きり', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('11967674-49fd-4a4c-ba25-61ade5b96622', NULL, 3, 'daily', 'その本は一度読んだきりで、そのままにしてある。', 'Cuốn sách đó tôi chỉ đọc 1 lần rồi để yên đó luôn.', 'その本は一度読んだ＿＿＿で、そのままにしてある。', 'きり', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c4a8ac6-be1c-4d7b-bfe7-1b399868fee8', NULL, 1, 'standard', '大学進学に先立って、弟は東京に引っ越しをした。', 'Trước khi học lên Đại học, em trai tôi đã chuyển lên Tokyo.', '大学進学＿＿＿、弟は東京に引っ越しをした。', 'に先立って', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c4a8ac6-be1c-4d7b-bfe7-1b399868fee8', NULL, 2, 'daily', '試合に先立って、選手たちは円陣を組んだ。', 'Trước trận đấu, các cầu thủ đã tập trung thành vòng tròn.', '試合＿＿＿、選手たちは円陣を組んだ。', 'に先立って', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c4a8ac6-be1c-4d7b-bfe7-1b399868fee8', NULL, 3, 'daily', '開店に先立って、店内の掃除を済ませた。', 'Trước khi khai trương, tôi đã dọn dẹp xong cửa hàng.', '開店＿＿＿、店内の掃除を済ませた。', 'に先立って', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8726b890-de11-473c-9ada-eb8c077bb7b3', NULL, 1, 'standard', '日本人に聞いたところ、私の発音は間違っていたようだ。', 'Sau khi hỏi người Nhật, có vẻ như phát âm của tôi bị sai.', '日本人に聞いた＿＿＿、私の発音は間違っていたようだ。', 'ところ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8726b890-de11-473c-9ada-eb8c077bb7b3', NULL, 2, 'daily', '調べたところ、原因はすぐに分かった。', 'Sau khi điều tra, nguyên nhân đã được tìm ra ngay.', '調べた＿＿＿、原因はすぐに分かった。', 'ところ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8726b890-de11-473c-9ada-eb8c077bb7b3', NULL, 3, 'daily', '試してみたところ、うまくいった。', 'Sau khi thử, mọi việc đã diễn ra suôn sẻ.', '試してみた＿＿＿、うまくいった。', 'ところ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ca4baf4e-8459-43d0-be5a-ce9bf8814b2d', NULL, 1, 'standard', 'このゲームは子供どころか、大人まで夢中になってしまう。', 'Cái game này chẳng những là trẻ con mà đến người lớn cũng đắm say với nó.', 'このゲームは子供＿＿＿、大人まで夢中になってしまう。', 'どころか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ca4baf4e-8459-43d0-be5a-ce9bf8814b2d', NULL, 2, 'daily', '彼は謝るどころか、逆に怒り出した。', 'Anh ta chẳng những không xin lỗi mà ngược lại còn nổi giận.', '彼は謝る＿＿＿、逆に怒り出した。', 'どころか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ca4baf4e-8459-43d0-be5a-ce9bf8814b2d', NULL, 3, 'daily', '涼しいどころか、真夏のように暑い。', 'Chẳng những không mát mẻ mà còn nóng như giữa mùa hè.', '涼しい＿＿＿、真夏のように暑い。', 'どころか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('56b679c0-a7b0-412b-b2df-ede417349226', NULL, 1, 'standard', '小さい事を気にしているようでは、おおらかな人にはなれない。', 'Nếu cứ để ý đến những điều nhỏ nhặt thì không thể trở thành người rộng lượng, thoáng tính được.', '小さい事を気にしている＿＿＿、おおらかな人にはなれない。', 'ようでは', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('56b679c0-a7b0-412b-b2df-ede417349226', NULL, 2, 'daily', 'そんなに遅く起きるようじゃ、仕事に間に合わないよ。', 'Cứ dậy muộn như thế thì không kịp giờ làm đâu.', 'そんなに遅く起きる＿＿＿、仕事に間に合わないよ。', 'ようじゃ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('56b679c0-a7b0-412b-b2df-ede417349226', NULL, 3, 'daily', 'そのくらいで諦めるようでは、目標は達成できない。', 'Nếu bỏ cuộc chỉ với chừng đó thì không thể đạt được mục tiêu.', 'そのくらいで諦める＿＿＿、目標は達成できない。', 'ようでは', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('83975527-6f65-4554-98ff-21c8a5612912', NULL, 1, 'standard', '彼は新人でありながら、態度が良くないので注意をする。', 'Anh ấy mặc dù là người mới thế nhưng thái độ không tốt nên tôi đã nhắc nhở.', '彼は新人であり＿＿＿、態度が良くないので注意をする。', 'ながら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('83975527-6f65-4554-98ff-21c8a5612912', NULL, 2, 'daily', '狭いながらも、居心地のいい部屋だ。', 'Mặc dù nhỏ nhưng đây là 1 căn phòng thoải mái.', '狭い＿＿＿、居心地のいい部屋だ。', 'ながらも', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('83975527-6f65-4554-98ff-21c8a5612912', NULL, 3, 'daily', '彼は忙しいながらも、時間を作って手伝ってくれた。', 'Mặc dù bận rộn nhưng anh ấy vẫn dành thời gian giúp đỡ tôi.', '彼は忙しい＿＿＿、時間を作って手伝ってくれた。', 'ながらも', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92fa2c07-487e-4986-ae14-a2050de06c26', NULL, 1, 'standard', '煙草は健康に良くないと分かりつつ、禁煙する事ができない。', 'Mặc dù biết thuốc lá không tốt cho sức khỏe thế nhưng tôi không thể bỏ được.', '煙草は健康に良くないと分かり＿＿＿、禁煙する事ができない。', 'つつ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92fa2c07-487e-4986-ae14-a2050de06c26', NULL, 2, 'daily', '音楽を聴きつつ、勉強をする。', 'Tôi vừa nghe nhạc vừa học bài.', '音楽を聴き＿＿＿、勉強をする。', 'つつ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('92fa2c07-487e-4986-ae14-a2050de06c26', NULL, 3, 'daily', '悪いと知りつつも、つい嘘をついてしまった。', 'Mặc dù biết là không tốt nhưng tôi vẫn lỡ nói dối.', '悪いと知り＿＿＿も、つい嘘をついてしまった。', 'つつ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('7197daa1-747d-450c-92d1-a6cd055de591', NULL, 1, 'standard', 'この仕事は大変なわりに給料が安いので、辞めようか悩んでいる。', 'Công việc này mặc dù vất vả mà lương lại ít nên tôi đang trăn trở xem có nên nghỉ hay không.', 'この仕事は大変な＿＿＿給料が安いので、辞めようか悩んでいる。', 'わりに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('7197daa1-747d-450c-92d1-a6cd055de591', NULL, 2, 'daily', '彼は勉強しないわりに、成績がいい。', 'Anh ấy dù không học hành gì mấy mà thành tích lại tốt.', '彼は勉強しない＿＿＿、成績がいい。', 'わりに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('7197daa1-747d-450c-92d1-a6cd055de591', NULL, 3, 'daily', '値段が高いわりには、あまり美味しくなかった。', 'So với giá tiền đắt thì món ăn lại không ngon lắm.', '値段が高い＿＿＿、あまり美味しくなかった。', 'わりには', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 'fill_blank', 'Điền vào chỗ trống: 大げんか＿＿＿その夫婦は離婚した。', 'の末に', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 'choose_meaning', 'Mẫu ngữ pháp "Vた／Nの ＋ 末(に)" (usage này) có nghĩa là gì?', 'Kể từ sau khi...thì mới.../Chỉ sau khi...mới... (nhận ra/hiểu ra sau khi trải qua)', 'Cuối cùng thì.../Kết quả là... (sau 1 quá trình dài, đắn đo)', 'Mặc dù.../So với...thì... (kết quả không tương xứng với tiêu chuẩn/điều kiện đã nêu)', 'E rằng.../Có khả năng... (nguy cơ xảy ra 1 điều không mong muốn)', 'Cuối cùng thì.../Kết quả là... (sau 1 quá trình dài, đắn đo)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('52f68e6b-4468-4651-aa0e-0f3292598636', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Cuối cùng thì.../Kết quả là... (sau 1 quá trình dài, đắn đo)"?', 'Vる／Vない／Nの ＋ おそれがある', 'V普／Aい／Aな／Nの ＋ わりに(は)', 'Vた／Nの ＋ 末(に)', 'N(の)／Vる ＋ に先立って', 'Vた／Nの ＋ 末(に)', 'generated');
